            <kbd style="background: rgba(255,255,255,0.1); padding: 3px 8px; border-radius: 6px; font-family: monospace; font-size: 11.5px; border: 1px solid rgba(255,255,255,0.15); color: #ffffff;">${o}+H</kbd>
